package io.translatetube.local.util

import java.util.Locale

/**
 * Pure selection logic for copying only the events that belong to one translation operation.
 * The ID is generated by the app and accepted only in UUID-like hexadecimal form.
 */
internal object TranslationDiagnosticPackPolicy {
    private val idPattern = Regex("""^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$""")
    private val fieldPattern = Regex("""(?m)^- 翻译诊断 ID：([0-9a-fA-F-]{36})\s*$""")

    fun normalizeId(value: String): String? =
        value.trim().takeIf(idPattern::matches)?.lowercase(Locale.ROOT)

    fun idFromRecord(record: AppLogRecord): String? =
        fieldPattern.find(record.details)?.groupValues?.getOrNull(1)?.let(::normalizeId)

    fun relatedRecords(records: List<AppLogRecord>, diagnosticId: String): List<AppLogRecord> {
        val id = normalizeId(diagnosticId) ?: return emptyList()
        return records.asSequence()
            .filter { idFromRecord(it) == id }
            .distinctBy {
                listOf(it.timestampMs, it.level, it.tag, it.message, it.details, it.thread)
            }
            .sortedBy { it.timestampMs }
            .toList()
    }

    /**
     * Merges translation-operation evidence into the selected incident repair package.
     *
     * Every retained event carrying the selected translation diagnostic ID is preserved,
     * even when that set exceeds the ordinary incident context limit. Other contextual events
     * continue to use the existing nearest-event limit.
     */
    fun mergeIncidentRecords(
        allRecords: List<AppLogRecord>,
        incidentContextRecords: List<AppLogRecord>,
        selected: AppLogRecord,
        maxContextRecords: Int = 80,
    ): List<AppLogRecord> {
        val translationEvents = idFromRecord(selected)
            ?.let { diagnosticId -> relatedRecords(allRecords, diagnosticId) }
            .orEmpty()
        // Explicit recovery links are high-value evidence. Preserve them before ordinary nearby
        // events so a busy operation cannot push its successful recovery out of the export.
        val recoveryEvents = incidentContextRecords.filter {
            selected.issueKey.isNotBlank() && it.resolvesIssueKey == selected.issueKey
        }
        val protectedKeys = (translationEvents + recoveryEvents + selected).map(::eventKey).toSet()
        val protectedCount = (translationEvents + recoveryEvents + selected)
            .distinctBy(::eventKey)
            .size
        val additionalContext = incidentContextRecords.asSequence()
            .filterNot { eventKey(it) in protectedKeys }
            .sortedBy { kotlin.math.abs(it.timestampMs - selected.timestampMs) }
            .take((maxContextRecords - protectedCount).coerceAtLeast(0))
            .toList()

        // All matching translation events and explicit recovery links survive even when they
        // exceed the ordinary context budget. The selected incident is always present exactly once.
        return (translationEvents + recoveryEvents + additionalContext + selected)
            .distinctBy(::eventKey)
            .sortedWith(compareBy<AppLogRecord> { it.timestampMs }.thenBy { it.sequence })
    }

    private fun eventKey(record: AppLogRecord): String =
        record.eventId.ifBlank {
            record.timestampMs.toString() + ":" + record.tag + ":" + record.message
        }
}
